-- Run once (seed_runs). Jharkhand Tier A leaders, generated by scraper/src/bihar/leaders-cli.ts from the curated
-- scraper/data/jh/leaders.json and leader-profiles.json: candidacy links (never moving curated or merged
-- persons), fill-only profile fields, and the leaders/cabinet watchlists of each Jharkhand manifest (written once;
-- admins edit them afterwards). Persons and image credits above the guard are idempotent and run every time.
SELECT NOT EXISTS (SELECT 1 FROM seed_runs WHERE name = 'seed_jh_leaders')
   AS seed_apply \gset
\if :seed_apply

-- Link each leader's candidacies to the best-linked person. A candidacy moves from a one-candidacy person or from a
-- person whose candidacies all belong to this leader (leaders.json is curated); never from a merge, a split or a
-- person with an admin-entered profile.
UPDATE candidates c SET person_id = (SELECT c.person_id FROM candidates c WHERE c.id IN ('edf2cc7d-9bcd-54f7-aea3-49c0a20594a0', 'efdebbae-1455-5597-815e-62ea20bcd05b', '2fa628f3-84bb-5007-9eb3-63455c4087db', '8db12470-f1bd-5641-9506-90a47709dc2e', '05b32aa7-4fde-57d2-ae38-4c00278a4207', '4143b3aa-87a6-57d6-aab6-436efdf9bdd7') ORDER BY (SELECT count(*) FROM candidates c2 WHERE c2.person_id = c.person_id) DESC, c.id LIMIT 1)
WHERE c.id IN ('edf2cc7d-9bcd-54f7-aea3-49c0a20594a0', 'efdebbae-1455-5597-815e-62ea20bcd05b', '2fa628f3-84bb-5007-9eb3-63455c4087db', '8db12470-f1bd-5641-9506-90a47709dc2e', '05b32aa7-4fde-57d2-ae38-4c00278a4207', '4143b3aa-87a6-57d6-aab6-436efdf9bdd7') AND c.person_id <> (SELECT c.person_id FROM candidates c WHERE c.id IN ('edf2cc7d-9bcd-54f7-aea3-49c0a20594a0', 'efdebbae-1455-5597-815e-62ea20bcd05b', '2fa628f3-84bb-5007-9eb3-63455c4087db', '8db12470-f1bd-5641-9506-90a47709dc2e', '05b32aa7-4fde-57d2-ae38-4c00278a4207', '4143b3aa-87a6-57d6-aab6-436efdf9bdd7') ORDER BY (SELECT count(*) FROM candidates c2 WHERE c2.person_id = c.person_id) DESC, c.id LIMIT 1)
  AND ((SELECT count(*) FROM candidates c2 WHERE c2.person_id = c.person_id) = 1
       OR NOT EXISTS (SELECT 1 FROM candidates c3 WHERE c3.person_id = c.person_id AND c3.id NOT IN ('edf2cc7d-9bcd-54f7-aea3-49c0a20594a0', 'efdebbae-1455-5597-815e-62ea20bcd05b', '2fa628f3-84bb-5007-9eb3-63455c4087db', '8db12470-f1bd-5641-9506-90a47709dc2e', '05b32aa7-4fde-57d2-ae38-4c00278a4207', '4143b3aa-87a6-57d6-aab6-436efdf9bdd7')))
  AND NOT EXISTS (SELECT 1 FROM person_merges pm WHERE pm.duplicate->>'id' = c.person_id::text OR pm.keeper_ref = c.person_id)
  AND NOT EXISTS (SELECT 1 FROM audit_logs al WHERE al.action = 'CANDIDATE_SPLIT' AND al.entity_type = 'candidate' AND al.entity_id = c.id::text)
  AND NOT EXISTS (SELECT 1 FROM persons pp WHERE pp.id = c.person_id AND (pp.photo_url IS NOT NULL OR pp.bio IS NOT NULL OR pp.wikipedia_url IS NOT NULL OR pp.date_of_birth IS NOT NULL));
